<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
:root {
  --blue: #3861FB;
  --navy: #0D1421;
  --gray: #808A9D;
  --green: #16c784;
  --red: #ea3943;
  --bg: #fff;
  --bg-alt: #f8f9fa;
  --bg-hover: #f0f2f5;
  --border: #eff2f5;
  --text: #0D1421;
  --text-secondary: #808A9D;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
}
html { font-size: 14px; }
body { font-family: var(--font); color: var(--text); background: var(--bg); line-height: 1.5; -webkit-font-smoothing: antialiased; }
a { color: var(--blue); text-decoration: none; }
a:hover { text-decoration: underline; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
.container { max-width: 1400px; margin: 0 auto; padding: 0 20px; }

/* NAV */
.nav { background: var(--bg); border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 100; }
.nav-inner { display: flex; align-items: center; height: 56px; gap: 24px; }
.nav-logo { font-weight: 700; font-size: 1.15rem; color: var(--navy); white-space: nowrap; display: flex; align-items: center; gap: 8px; }
.nav-logo svg { width: 28px; height: 28px; }
.nav-links { display: flex; gap: 4px; flex: 1; }
.nav-links > .nav-item { position: relative; }
.nav-links .nav-link { padding: 6px 12px; border-radius: 6px; font-size: .875rem; font-weight: 500; color: var(--navy); transition: background .15s; white-space: nowrap; }
.nav-links .nav-link:hover { background: var(--bg-hover); text-decoration: none; }
.nav-dropdown { display: none; position: absolute; top: 100%; left: 0; background: var(--bg); border: 1px solid var(--border); border-radius: 8px; padding: 8px 0; min-width: 220px; box-shadow: 0 8px 24px rgba(0,0,0,.1); z-index: 200; }
.nav-item:hover .nav-dropdown { display: block; }
.nav-dropdown a { display: block; padding: 6px 16px; font-size: .825rem; color: var(--navy); white-space: nowrap; }
.nav-dropdown a:hover { background: var(--bg-hover); text-decoration: none; }
.nav-auth { display: flex; gap: 8px; align-items: center; }
.btn-login { padding: 7px 16px; font-size: .825rem; font-weight: 500; color: var(--navy); border-radius: 6px; }
.btn-login:hover { background: var(--bg-hover); }
.btn-signup { padding: 7px 16px; font-size: .825rem; font-weight: 600; color: #fff; background: var(--blue); border-radius: 6px; transition: opacity .15s; }
.btn-signup:hover { opacity: .9; }

/* TOP BAR METRICS */
.top-bar { background: var(--bg-alt); border-bottom: 1px solid var(--border); padding: 10px 0; }
.top-bar-inner { display: flex; align-items: center; gap: 32px; flex-wrap: wrap; }
.stat-item { display: flex; align-items: center; gap: 6px; font-size: .825rem; white-space: nowrap; }
.stat-label { color: var(--gray); font-weight: 500; }
.stat-value { font-weight: 600; font-variant-numeric: tabular-nums; }
.stat-change { font-weight: 500; font-size: .75rem; }
.stat-change.up { color: var(--green); }
.stat-change.down { color: var(--red); }
.stat-badge { display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 4px; font-size: .75rem; font-weight: 600; }
.stat-badge.neutral { background: #f0f2f5; color: var(--gray); }
.stat-divider { width: 1px; height: 20px; background: var(--border); }

/* PROMO BANNER */
.promo-banner { border-bottom: 1px solid var(--border); overflow: hidden; position: relative; }
.promo-track { display: flex; transition: transform .4s ease; }
.promo-slide { min-width: 100%; padding: 14px 0; text-align: center; font-size: .875rem; font-weight: 500; }
.promo-slide .promo-highlight { color: var(--blue); font-weight: 600; }
.promo-arrow { position: absolute; top: 50%; transform: translateY(-50%); width: 28px; height: 28px; border-radius: 50%; background: var(--bg); border: 1px solid var(--border); display: flex; align-items: center; justify-content: center; font-size: .75rem; color: var(--gray); z-index: 2; transition: all .15s; }
.promo-arrow:hover { background: var(--bg-hover); color: var(--navy); }
.promo-arrow.left { left: 12px; }
.promo-arrow.right { right: 12px; }
.promo-dots { display: flex; justify-content: center; gap: 6px; padding: 4px 0 10px; }
.promo-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--border); cursor: pointer; transition: background .15s; }
.promo-dot.active { background: var(--blue); }

/* AI ALERTS BAR */
.ai-bar { border-bottom: 1px solid var(--border); padding: 12px 0; }
.ai-bar-inner { display: flex; align-items: center; gap: 12px; }
.ai-badge { background: linear-gradient(135deg, #3861FB, #7c3aed); color: #fff; padding: 4px 10px; border-radius: 6px; font-size: .75rem; font-weight: 700; white-space: nowrap; }
.ai-prompt { flex: 1; display: flex; align-items: center; gap: 8px; }
.ai-prompt-input { flex: 1; background: var(--bg-alt); border: 1px solid var(--border); border-radius: 8px; padding: 8px 14px; font-size: .825rem; color: var(--navy); outline: none; font-family: var(--font); }
.ai-prompt-input::placeholder { color: var(--gray); }
.ai-suggestions { display: flex; gap: 8px; overflow-x: auto; padding: 2px 0; scrollbar-width: none; }
.ai-suggestions::-webkit-scrollbar { display: none; }
.ai-suggestion { padding: 5px 12px; border-radius: 20px; border: 1px solid var(--border); font-size: .75rem; color: var(--gray); white-space: nowrap; transition: all .15s; }
.ai-suggestion:hover { border-color: var(--blue); color: var(--blue); background: rgba(56,97,251,.04); }

/* CATEGORY & NETWORK TABS */
.tabs-section { padding: 16px 0 0; }
.category-tabs { display: flex; gap: 4px; margin-bottom: 12px; overflow-x: auto; scrollbar-width: none; }
.category-tabs::-webkit-scrollbar { display: none; }
.cat-tab { padding: 7px 16px; border-radius: 8px; font-size: .825rem; font-weight: 500; color: var(--gray); transition: all .15s; white-space: nowrap; }
.cat-tab:hover { color: var(--navy); background: var(--bg-hover); }
.cat-tab.active { color: var(--navy); background: var(--bg-alt); font-weight: 600; box-shadow: inset 0 -2px 0 var(--blue); }
.network-tabs { display: flex; gap: 4px; margin-bottom: 16px; overflow-x: auto; scrollbar-width: none; }
.network-tabs::-webkit-scrollbar { display: none; }
.net-tab { padding: 5px 12px; border-radius: 6px; font-size: .75rem; font-weight: 500; color: var(--gray); border: 1px solid var(--border); transition: all .15s; white-space: nowrap; }
.net-tab:hover { border-color: var(--blue); color: var(--blue); }
.net-tab.active { border-color: var(--blue); color: var(--blue); background: rgba(56,97,251,.06); }

/* INDEX TRACKER ROW */
.index-row { display: flex; align-items: center; gap: 16px; padding: 10px 16px; background: var(--bg-alt); border: 1px solid var(--border); border-radius: 8px; margin-bottom: 12px; font-size: .825rem; }
.index-name { font-weight: 600; color: var(--navy); }
.index-symbol { color: var(--gray); font-size: .75rem; margin-left: 4px; }
.index-price { font-weight: 600; font-variant-numeric: tabular-nums; }
.index-change { font-variant-numeric: tabular-nums; font-size: .75rem; }

/* TABLE CONTROLS */
.table-controls { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; flex-wrap: wrap; gap: 8px; }
.table-controls-left { display: flex; gap: 8px; align-items: center; }
.table-controls-right { display: flex; gap: 8px; align-items: center; }
.ctrl-btn { padding: 6px 12px; border-radius: 6px; font-size: .8rem; font-weight: 500; color: var(--navy); border: 1px solid var(--border); transition: all .15s; display: flex; align-items: center; gap: 4px; }
.ctrl-btn:hover { border-color: var(--blue); color: var(--blue); }
.ctrl-btn.active { border-color: var(--blue); color: var(--blue); background: rgba(56,97,251,.06); }
.ctrl-btn svg { width: 14px; height: 14px; }

