thead th { position: sticky; top: 56px; background: var(--bg-alt); padding: 10px 12px; font-size: .7rem; font-weight: 600; color: var(--gray); text-transform: uppercase; letter-spacing: .03em; border-bottom: 1px solid var(--border); white-space: nowrap; cursor: pointer; user-select: none; }
thead th:hover { color: var(--navy); }
thead th.sorted { color: var(--navy); }
