td.td-name .coin-icon { width: 22px; height: 22px; border-radius: 50%; margin-right: 8px; vertical-align: middle; display: inline-flex; align-items: center; justify-content: center; font-size: .6rem; font-weight: 700; color: #fff; }
td.td-name .coin-symbol { color: var(--gray); font-size: .75rem; margin-left: 6px; }
