td.td-sparkline { text-align: center; width: 120px; }

/* PAGINATION */
.pagination { display: flex; align-items: center; justify-content: center; gap: 4px; padding: 20px 0; }
.page-btn { width: 36px; height: 36px; border-radius: 6px; font-size: .825rem; font-weight: 500; color: var(--navy); border: 1px solid var(--border); display: flex; align-items: center; justify-content: center; transition: all .15s; }
.page-btn:hover { border-color: var(--blue); color: var(--blue); }
.page-btn.active { background: var(--blue); color: #fff; border-color: var(--blue); }
.page-ellipsis { width: 36px; height: 36px; display: flex; align-items: center; justify-content: center; color: var(--gray); }
.page-info { font-size: .8rem; color: var(--gray); margin-left: 16px; }

/* MARKET SUMMARY */
.market-summary { padding: 24px 0; border-top: 1px solid var(--border); }
.market-summary p { font-size: .875rem; color: var(--text-secondary); line-height: 1.7; max-width: 900px; }
.market-summary strong { color: var(--navy); }
.read-more-btn { color: var(--blue); font-size: .825rem; font-weight: 500; background: none; border: none; padding: 0; margin-top: 4px; }
.read-more-btn:hover { text-decoration: underline; }
.summary-extra { display: none; margin-top: 8px; }
.summary-extra.open { display: block; }

/* INFO CONTENT */
.info-section { padding: 24px 0; border-top: 1px solid var(--border); }
.info-section h2 { font-size: 1.1rem; font-weight: 700; margin-bottom: 12px; }
