.info-section p { font-size: .875rem; color: var(--text-secondary); line-height: 1.7; max-width: 900px; }

/* FOOTER */
.footer { background: var(--bg-alt); border-top: 1px solid var(--border); padding: 32px 0 20px; margin-top: 24px; }
.footer-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; margin-bottom: 24px; }
