function formatPrice(p) {
  if (p >= 1000) return '$' + p.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
  if (p >= 1) return '$' + p.toFixed(2);
  if (p >= 0.01) return '$' + p.toFixed(4);
  return '$' + p.toFixed(8);
}
function formatMcap(v) {
  if (v >= 1e12) return '$' + (v/1e12).toFixed(2) + 'T';
  if (v >= 1e9) return '$' + (v/1e9).toFixed(2) + 'B';
  if (v >= 1e6) return '$' + (v/1e6).toFixed(2) + 'M';
  return '$' + v.toLocaleString();
}
function formatVol(v) {
  if (v >= 1e9) return '$' + (v/1e9).toFixed(2) + 'B';
  if (v >= 1e6) return '$' + (v/1e6).toFixed(2) + 'M';
  return '$' + v.toLocaleString();
}
function pctClass(v) { return v >= 0 ? 'up' : 'down'; }
function pctStr(v) { return (v >= 0 ? '+' : '') + v.toFixed(2) + '%'; }

function generateSparkline(d7) {
  const pts = 7;
  const base = 50;
  const amp = Math.abs(d7) * 2 + 5;
  let points = [];
  for (let i = 0; i < pts; i++) {
    const y = base - amp * (i / (pts-1)) + (Math.random() - 0.5) * amp * 0.3;
    points.push(y);
  }
  if (d7 >= 0) {
    points[0] = base + amp * 0.3;
    points[pts-1] = base - amp * 0.5;
  } else {
    points[0] = base - amp * 0.3;
    points[pts-1] = base + amp * 0.5;
  }
  const min = Math.min(...points);
  const max = Math.max(...points);
  const range = max - min || 1;
  const w = 100, h = 32;
  const coords = points.map((p, i) => `${(i/(pts-1))*w},${h - ((p-min)/range)*h}`).join(' ');
  const color = d7 >= 0 ? 'var(--green)' : 'var(--red)';
  return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><polyline points="${coords}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}

function renderTable(data) {
  const tbody = document.getElementById('cryptoBody');
  tbody.innerHTML = '';
  data.forEach(c => {
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td class="td-rank">${c.rank}</td>
      <td class="td-name"><span class="coin-icon" style="background:${c.color}">${c.symbol.charAt(0)}</span>${c.name}<span class="coin-symbol">${c.symbol}</span></td>
      <td class="td-price">${formatPrice(c.price)}</td>
      <td class="td-change ${pctClass(c.h1)}">${pctStr(c.h1)}</td>
      <td class="td-change ${pctClass(c.h24)}">${pctStr(c.h24)}</td>
      <td class="td-change ${pctClass(c.d7)}">${pctStr(c.d7)}</td>
      <td class="td-mcap">${formatMcap(c.mcap)}</td>
      <td class="td-vol">${formatVol(c.vol)}</td>
      <td class="td-supply"><span class="supply-ticker">${c.supply.split(' ')[1]}</span> ${c.supply.split(' ')[0]}</td>
      <td class="td-sparkline">${generateSparkline(c.d7)}</td>
    `;
    tbody.appendChild(tr);
  });
}

// Initial render
renderTable(cryptoData);

// PROMO BANNER
let promoIdx = 0;
const promoTrack = document.getElementById('promoTrack');
const promoDots = document.querySelectorAll('.promo-dot');
function updatePromo() {
  promoTrack.style.transform = `translateX(-${promoIdx * 100}%)`;
  promoDots.forEach((d,i) => d.classList.toggle('active', i === promoIdx));
}
function slidePromo(dir) { promoIdx = (promoIdx + dir + 3) % 3; updatePromo(); }
function goToSlide(i) { promoIdx = i; updatePromo(); }
setInterval(() => slidePromo(1), 5000);

// CATEGORY TABS
function setCategory(btn) {
  document.querySelectorAll('.cat-tab').forEach(t => t.classList.remove('active'));
  btn.classList.add('active');
  const cat = btn.dataset.cat;
  let filtered = [...cryptoData];
  if (cat === 'trending') filtered = cryptoData.filter(c => c.h24 > 2).sort((a,b) => b.h24 - a.h24);
  else if (cat === 'watchlist') filtered = cryptoData.slice(0, 10);
  else if (cat === 'prediction') filtered = cryptoData.slice(5, 15);
  else if (cat === 'visited') filtered = cryptoData.slice(0, 20);
  else if (cat === 'new') filtered = cryptoData.slice(80, 100);
  else filtered = [...cryptoData];
  filtered.forEach((c,i) => c.rank = i + 1);
  renderTable(filtered);
}

// NETWORK TABS
function setNetwork(btn) {
  document.querySelectorAll('.net-tab').forEach(t => t.classList.remove('active'));
  btn.classList.add('active');
  const net = btn.dataset.net;
  let filtered = [...cryptoData];
  if (net !== 'all' && net !== 'more') filtered = cryptoData.filter(c => c.net === net);
  filtered.forEach((c,i) => c.rank = i + 1);
  renderTable(filtered);
}

// COLUMNS TOGGLE
function toggleColumns() {
  const dd = document.getElementById('columnsDropdown');
  dd.classList.toggle('open');
}
document.querySelectorAll('.col-toggle input').forEach(cb => {
  cb.addEventListener('change', function() {
    const col = parseInt(this.dataset.col);
    const ths = document.querySelectorAll('#cryptoTable thead th');
    const rows = document.querySelectorAll('#cryptoTable tbody tr');
    if (ths[col]) ths[col].style.display = this.checked ? '' : 'none';
    rows.forEach(r => { if (r.cells[col]) r.cells[col].style.display = this.checked ? '' : 'none'; });
  });
});
document.addEventListener('click', function(e) {
  if (!e.target.closest('#columnsBtn') && !e.target.closest('#columnsDropdown')) {
    document.getElementById('columnsDropdown').classList.remove('open');
  }
});

// FILTERS TOGGLE
function toggleFilters() {
  const fp = document.getElementById('filterPanel');
  const fb = document.getElementById('filtersBtn');
  fp.classList.toggle('open');
  fb.classList.toggle('active');
}
function applyFilters() {
  // Visual feedback only — closes panel
  document.getElementById('filterPanel').classList.remove('open');
  document.getElementById('filtersBtn').classList.remove('active');
}

// PAGINATION
document.querySelectorAll('.page-btn').forEach(btn => {
  btn.addEventListener('click', function() {
    document.querySelectorAll('.page-btn').forEach(b => b.classList.remove('active'));
    this.classList.add('active');
  });
});

// MARKET SUMMARY ACCORDION
function toggleSummary() {
  const extra = document.getElementById('summaryExtra');
  const btn = document.getElementById('readMoreBtn');
  const isOpen = extra.classList.toggle('open');
  btn.textContent = isOpen ? 'Show Less' : 'Read More';
}

// SORT TABLE HEADERS
document.querySelectorAll('#cryptoTable thead th').forEach((th, i) => {
  th.addEventListener('click', function() {
    document.querySelectorAll('#cryptoTable thead th').forEach(h => h.classList.remove('sorted'));
    this.classList.add('sorted');
    const rows = Array.from(document.querySelectorAll('#cryptoBody tr'));
    const asc = this.dataset.sort !== 'asc';
    document.querySelectorAll('#cryptoTable thead th').forEach(h => h.dataset.sort = '');
    this.dataset.sort = asc ? 'asc' : 'desc';
    rows.sort((a, b) => {
      let av = a.cells[i]?.textContent?.replace(/[$%,+]/g, '') || '0';
      let bv = b.cells[i]?.textContent?.replace(/[$%,+]/g, '') || '0';
      const na = parseFloat(av.replace(/[^\d.-]/g, ''));
      const nb = parseFloat(bv.replace(/[^\d.-]/g, ''));
      if (!isNaN(na) && !isNaN(nb)) return asc ? na - nb : nb - na;
      return asc ? av.localeCompare(bv) : bv.localeCompare(av);
    });
    const tbody = document.getElementById('cryptoBody');
    rows.forEach(r => tbody.appendChild(r));
  });
});
</script>
